namespace sv_db354f5dcd464957ae953868d4d6e4a5.Services;

public sealed class Recipe
{
    public required int Id { get; init; }
    public required string Title { get; init; }
    public required string Description { get; init; }
    public required int PrepTimeMinutes { get; init; }
}

public interface IRecipeService
{
    Task<List<Recipe>> GetByCuisineAsync(int cuisineId, CancellationToken cancellationToken);
}

public sealed class RecipeService : IRecipeService
{
    private static readonly Dictionary<int, List<Recipe>> SeedData = new()
    {
        [1] = new List<Recipe>
        {
            new() { Id = 1, Title = "Margherita Pizza", Description = "Classic pizza with tomato sauce, mozzarella, and fresh basil.", PrepTimeMinutes = 30 },
            new() { Id = 2, Title = "Spaghetti Carbonara", Description = "Creamy pasta with pancetta, egg yolk, and pecorino romano.", PrepTimeMinutes = 25 },
            new() { Id = 3, Title = "Tiramisu", Description = "Layered coffee-flavored dessert with mascarpone cream.", PrepTimeMinutes = 45 },
        },
        [2] = new List<Recipe>
        {
            new() { Id = 4, Title = "Sushi Rolls", Description = "Fresh fish and vegetables wrapped in seasoned rice and nori.", PrepTimeMinutes = 50 },
            new() { Id = 5, Title = "Ramen", Description = "Rich pork bone broth with noodles, chashu, and soft-boiled egg.", PrepTimeMinutes = 60 },
            new() { Id = 6, Title = "Tempura", Description = "Lightly battered and deep-fried shrimp and vegetables.", PrepTimeMinutes = 20 },
        },
        [3] = new List<Recipe>
        {
            new() { Id = 7, Title = "Tacos al Pastor", Description = "Marinated pork tacos with pineapple, onion, and cilantro.", PrepTimeMinutes = 40 },
            new() { Id = 8, Title = "Guacamole", Description = "Fresh avocado dip with lime, tomato, and jalapeño.", PrepTimeMinutes = 10 },
            new() { Id = 9, Title = "Churros", Description = "Fried dough pastry coated in cinnamon sugar with chocolate sauce.", PrepTimeMinutes = 35 },
        },
    };

    public async Task<List<Recipe>> GetByCuisineAsync(int cuisineId, CancellationToken cancellationToken)
    {
        await Task.Delay(2000, cancellationToken);

        if (SeedData.TryGetValue(cuisineId, out var recipes))
        {
            return recipes.Select(r => r).ToList();
        }

        return new List<Recipe>();
    }
}

@page "/recipes/{CuisineId:int}"
@using sv_db354f5dcd464957ae953868d4d6e4a5.Services
@rendermode InteractiveServer
@implements IDisposable
@inject IRecipeService RecipeService
@inject ILogger<Recipes> Logger
@inject NavigationManager Navigation

<PageTitle>Recipes</PageTitle>

<h1>Recipes</h1>

<nav style="margin-bottom:1rem">
    <a href="/recipes/1">Italian</a> |
    <a href="/recipes/2">Japanese</a> |
    <a href="/recipes/3">Mexican</a>
</nav>

@if (_recipes is not null)
{
    <div style="margin-bottom:0.5rem">
        <label>
            Sort:
            <select @bind="SelectedSort">
                <option value="newest">Newest</option>
                <option value="popular">Popular</option>
            </select>
        </label>
    </div>
}

@if (_errorMessage is not null)
{
    <div role="alert" style="border:1px solid #c00;padding:1rem;border-radius:4px;background:#fff0f0;color:#900">
        <p>@_errorMessage</p>
        <button @onclick="Retry">Retry</button>
    </div>
}
else if (_recipes is null)
{
    <p><em>Loading recipes…</em></p>
}
else
{
    @if (_isRefreshing)
    {
        <p><em>Refreshing…</em></p>
    }

    <table>
        <thead>
            <tr>
                <th>Title</th>
                <th>Description</th>
                <th>Prep Time</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var recipe in DisplayedRecipes)
            {
                <tr>
                    <td>@recipe.Title</td>
                    <td>@recipe.Description</td>
                    <td>@recipe.PrepTimeMinutes min</td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    [Parameter]
    public int CuisineId { get; set; }

    [SupplyParameterFromQuery(Name = "sort")]
    public string? Sort { get; set; }

    private List<Recipe>? _recipes;
    private bool _isRefreshing;
    private string? _errorMessage;
    private int _loadedCuisineId;

    private CancellationTokenSource? _loadCts;
    private readonly CancellationTokenSource _disposalCts = new();

    private string SelectedSort
    {
        get => string.Equals(Sort, "popular", StringComparison.OrdinalIgnoreCase) ? "popular" : "newest";
        set => Navigation.NavigateTo(
            Navigation.GetUriWithQueryParameter("sort", value),
            replace: true);
    }

    private IEnumerable<Recipe> DisplayedRecipes =>
        _recipes is null
            ? Enumerable.Empty<Recipe>()
            : string.Equals(Sort, "popular", StringComparison.OrdinalIgnoreCase)
                ? _recipes.OrderByDescending(r => r.Id)
                : _recipes.OrderBy(r => r.Id);

    protected override Task OnParametersSetAsync()
    {
        if (CuisineId != _loadedCuisineId)
        {
            return LoadRecipesAsync();
        }

        return Task.CompletedTask;
    }

    private async Task LoadRecipesAsync()
    {
        // Cancel any in-flight request for a previous cuisine.
        if (_loadCts is not null)
        {
            await _loadCts.CancelAsync();
            _loadCts.Dispose();
        }

        _loadCts = CancellationTokenSource.CreateLinkedTokenSource(_disposalCts.Token);

        _isRefreshing = _recipes is not null;
        _errorMessage = null;
        _loadedCuisineId = CuisineId;

        var token = _loadCts.Token;

        try
        {
            var result = await RecipeService.GetByCuisineAsync(CuisineId, token);

            token.ThrowIfCancellationRequested();

            _recipes = result;
            _isRefreshing = false;
        }
        catch (OperationCanceledException) when (token.IsCancellationRequested)
        {
            // Superseded by a newer load or the component was disposed — do nothing.
        }
        catch (TimeoutException ex)
        {
            Logger.LogError(ex, "Timeout loading recipes for cuisine {CuisineId}", CuisineId);
            _isRefreshing = false;
            _errorMessage = "The request timed out. Please check your connection and try again.";
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Error loading recipes for cuisine {CuisineId}", CuisineId);
            _isRefreshing = false;
            _errorMessage = "Something went wrong while loading recipes. Please try again.";
        }
    }

    private Task Retry() => LoadRecipesAsync();

    public void Dispose()
    {
        _disposalCts.Cancel();
        _disposalCts.Dispose();
        _loadCts?.Dispose();
    }
}

