@page "/recipes/{CuisineId:int}"
@using sv_db354f5dcd464957ae953868d4d6e4a5.Services
@rendermode InteractiveServer
@implements IDisposable
@inject IRecipeService RecipeService
@inject ILogger<Recipes> Logger
@inject NavigationManager Navigation

<PageTitle>Recipes</PageTitle>

<h1>Recipes</h1>

<nav style="margin-bottom:1rem">
    <a href="/recipes/1">Italian</a> |
    <a href="/recipes/2">Japanese</a> |
    <a href="/recipes/3">Mexican</a>
</nav>

@if (_recipes is not null)
{
    <div style="margin-bottom:0.5rem">
        <label>
            Sort:
            <select @bind="SelectedSort">
                <option value="newest">Newest</option>
                <option value="popular">Popular</option>
            </select>
        </label>
    </div>
}

@if (_errorMessage is not null)
{
    <div role="alert" style="border:1px solid #c00;padding:1rem;border-radius:4px;background:#fff0f0;color:#900">
        <p>@_errorMessage</p>
        <button @onclick="Retry">Retry</button>
    </div>
}
else if (_recipes is null)
{
    <p><em>Loading recipes…</em></p>
}
else
{
    @if (_isRefreshing)
    {
        <p><em>Refreshing…</em></p>
    }

    <table>
        <thead>
            <tr>
                <th>Title</th>
                <th>Description</th>
                <th>Prep Time</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var recipe in DisplayedRecipes)
            {
                <tr>
                    <td>@recipe.Title</td>
                    <td>@recipe.Description</td>
