        set => Navigation.NavigateTo(
            Navigation.GetUriWithQueryParameter("sort", value),
            replace: true);
    }

    private IEnumerable<Recipe> DisplayedRecipes =>
        _recipes is null
            ? Enumerable.Empty<Recipe>()
            : string.Equals(Sort, "popular", StringComparison.OrdinalIgnoreCase)
                ? _recipes.OrderByDescending(r => r.Id)
                : _recipes.OrderBy(r => r.Id);

    protected override Task OnParametersSetAsync()
    {
        if (CuisineId != _loadedCuisineId)
        {
            return LoadRecipesAsync();
        }

        return Task.CompletedTask;
    }

    private async Task LoadRecipesAsync()
    {
        // Cancel any in-flight request for a previous cuisine.
        if (_loadCts is not null)
        {
            await _loadCts.CancelAsync();
            _loadCts.Dispose();
        }

        _loadCts = CancellationTokenSource.CreateLinkedTokenSource(_disposalCts.Token);

        _isRefreshing = _recipes is not null;
        _errorMessage = null;
        _loadedCuisineId = CuisineId;

        var token = _loadCts.Token;

        try
        {
            var result = await RecipeService.GetByCuisineAsync(CuisineId, token);

            token.ThrowIfCancellationRequested();

            _recipes = result;
            _isRefreshing = false;
        }
        catch (OperationCanceledException) when (token.IsCancellationRequested)
        {
            // Superseded by a newer load or the component was disposed — do nothing.
        }
        catch (TimeoutException ex)
        {
            Logger.LogError(ex, "Timeout loading recipes for cuisine {CuisineId}", CuisineId);
            _isRefreshing = false;
            _errorMessage = "The request timed out. Please check your connection and try again.";
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Error loading recipes for cuisine {CuisineId}", CuisineId);
            _isRefreshing = false;
            _errorMessage = "Something went wrong while loading recipes. Please try again.";
        }
    }

    private Task Retry() => LoadRecipesAsync();

    public void Dispose()
    {
        _disposalCts.Cancel();
        _disposalCts.Dispose();
        _loadCts?.Dispose();
    }
}

